# Generated by scripts/build_bridges.py from bridges/_core.py and bridges/adapters/gimp.py.
# Do not edit: change those files and run python3 scripts/build_bridges.py.
# Holds no token: the bridge reads it from LIBREMODULAR_TOKEN_PATH or the default path.

"""Common core of the LibreModular-MCP bridges: protocol, token and script execution.

Why this module exists
A bridge runs scripts with the user's rights inside an application. Who may talk
to it, how much it reads and how a script runs are decided once, here, so that an
application only adds an adapter and no adapter can weaken a check.
"""

import errno
import hmac
import io
import json
import os
import socket
import stat
import sys
import threading
import time
import traceback

# The only address a bridge listens on. It is a constant on purpose: no
# parameter, environment variable or configuration key can change it.
LISTEN_ADDRESS = "127.0.0.1"
PROTOCOL_VERSION = 1
BRIDGE_VERSION = "1"
# A line longer than this, in bytes and without its newline, closes the connection.
MAX_LINE_BYTES = 8 * 1024 * 1024
# How long a new connection may stay silent before its first line.
HELLO_TIMEOUT_S = 5.0
# The file name scripts are compiled under, so that tracebacks point at their text.
SCRIPT_FILENAME = "<libremodular>"
# What an adapter reports as its version when the application's API cannot be imported.
UNKNOWN_VERSION = "unknown"
# Files created while a script or a capture runs are private to the user.
PRIVATE_UMASK = 0o077
TOKEN_HEX_LENGTH = 64
TOKEN_READ_CAP = 4096

_READ_CHUNK = 64 * 1024
_ACCEPT_POLL_S = 0.2
_LISTEN_BACKLOG = 8
# What a script may print, per stream, before the rest is dropped.
_CAPTURE_LIMIT = MAX_LINE_BYTES // 16
# Each text of an answer that would not fit in one line is cut to this length.
_FALLBACK_TEXT = 64 * 1024
_TRUNCATED = "\n[truncated by the bridge]"
_WARNING = "libremodular bridge warning: "
_HEX_DIGITS = b"0123456789abcdefABCDEF"


class BridgeError(Exception):
    """The bridge cannot start. The message never contains the token."""


# --------------------------------------------------------------------------
# The token
# --------------------------------------------------------------------------


def _read_token(token_path):
    """Read the token from a private regular file of the current user."""
    path = os.fspath(token_path)
    flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOCTTY
    try:
        descriptor = os.open(path, flags)
    except OSError as error:
        if error.errno == errno.ELOOP:
            raise BridgeError("the token file %s is a symbolic link" % path) from None
        raise BridgeError(
            "cannot open the token file %s: %s" % (path, error.strerror)
        ) from None
    try:
        info = os.fstat(descriptor)
        if not stat.S_ISREG(info.st_mode):
            raise BridgeError("the token file %s is not a regular file" % path)
        if info.st_uid != os.geteuid():
            raise BridgeError("the token file %s belongs to another user" % path)
        if info.st_mode & 0o077:
            raise BridgeError(
                "the token file %s is open to the group or to others; run chmod 600 on it"
                % path
            )
        data = b""
        while len(data) <= TOKEN_READ_CAP:
            chunk = os.read(descriptor, TOKEN_READ_CAP + 1 - len(data))
            if not chunk:
                break
            data += chunk
    finally:
        os.close(descriptor)
    while data.endswith(b"\n"):
        data = data[:-1]
    if len(data) != TOKEN_HEX_LENGTH or any(byte not in _HEX_DIGITS for byte in data):
        raise BridgeError(
            "the token file %s does not hold a token made by libremodular-mcp init" % path
        )
    return data


# --------------------------------------------------------------------------
# Lines and answers
# --------------------------------------------------------------------------


class _LineReader:
    """Reads lines from a socket without ever holding much more than one line."""

    def __init__(self, connection):
        self._connection = connection
        self._buffer = bytearray()

    def read_line(self, deadline):
        """One line without its newline; None when the connection ends, the
        monotonic `deadline` passes, or the line exceeds MAX_LINE_BYTES."""
        while True:
            end = self._buffer.find(b"\n")
            if end >= 0:
                if end > MAX_LINE_BYTES:
                    return None
                line = bytes(self._buffer[:end])
                del self._buffer[: end + 1]
                return line
            if len(self._buffer) > MAX_LINE_BYTES:
                return None
            if deadline is None:
                self._connection.settimeout(None)
            else:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return None
                self._connection.settimeout(remaining)
            room = min(_READ_CHUNK, MAX_LINE_BYTES + 1 - len(self._buffer))
            try:
                chunk = self._connection.recv(room)
            except socket.timeout:
                return None
            except OSError:
                return None
            if not chunk:
                return None
            self._buffer += chunk


def _parse_object(line):
    """The JSON object a line holds, or None for anything else."""
    try:
        value = json.loads(line.decode("utf-8"))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _dump(value):
    # A lone surrogate cannot travel as UTF-8: it becomes a replacement character.
    text = json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    return text.encode("utf-8", "replace")


def _json_copy(value):
    """A plain JSON copy of `value`, or raise when it is not serialisable."""
    return json.loads(json.dumps(value, allow_nan=False))


def _cut(text):
    if isinstance(text, str) and len(text) > _FALLBACK_TEXT:
        return text[:_FALLBACK_TEXT] + _TRUNCATED
    return text


def _encode(answer):
    """The answer as one line that fits in MAX_LINE_BYTES."""
    try:
        line = _dump(answer)
    except (TypeError, ValueError):
        line = None
    if line is not None and len(line) <= MAX_LINE_BYTES:
        return line
    smaller = dict(answer)
    warning = "the answer was too large for one protocol line and was reduced\n"
    if "result" in smaller:
        smaller["result"] = None
        smaller["stderr"] = _cut(smaller.get("stderr", "")) + "\n" + _WARNING + warning
    if "state" in smaller:
        smaller["state"] = {}
        smaller["warnings"] = [_cut(item) for item in smaller.get("warnings", [])[:16]]
        smaller["warnings"].append(warning.strip())
    for key in ("stdout", "stderr"):
        if key in smaller:
            smaller[key] = _cut(smaller[key])
    error = smaller.get("error")
    if isinstance(error, dict):
        smaller["error"] = {key: _cut(value) for key, value in error.items()}
    try:
        line = _dump(smaller)
    except (TypeError, ValueError):
        line = None
    if line is not None and len(line) <= MAX_LINE_BYTES:
        return line
    return _dump(
        {
            "id": answer.get("id"),
            "ok": False,
            "error": {
                "type": "AnswerTooLarge",
                "message": "the answer could not fit in one protocol line",
                "traceback": "",
            },
        }
    )


def _send(connection, answer):
    connection.sendall(_encode(answer) + b"\n")


def _failure(kind, message, traceback_text=""):
    return {
        "ok": False,
        "error": {"type": kind, "message": message, "traceback": traceback_text},
    }


def _text_of(error):
    try:
        return str(error)
    except Exception:
        return "<the exception could not be shown>"


def _peer_allowed(peer):
    return isinstance(peer, tuple) and len(peer) >= 1 and peer[0] == LISTEN_ADDRESS


# --------------------------------------------------------------------------
# Running a script
# --------------------------------------------------------------------------


class _Capture(io.TextIOBase):
    """Collects what a script prints, up to a bound, so that a runaway loop of
    prints cannot exhaust the memory of the application."""

    encoding = "utf-8"
    errors = "strict"

    def __init__(self):
        super().__init__()
        self._parts = []
        self._size = 0
        self._dropped = False

    def writable(self):
        return True

    def write(self, text):
        if not isinstance(text, str):
            raise TypeError("write() argument must be str, not %s" % type(text).__name__)
        room = _CAPTURE_LIMIT - self._size
        if room > 0:
            kept = text[:room]
            self._parts.append(kept)
            self._size += len(kept)
        if len(text) > max(room, 0):
            self._dropped = True
        return len(text)

    def text(self):
        joined = "".join(self._parts)
        return joined + _TRUNCATED if self._dropped else joined


def _with_private_umask(function, *arguments):
    """Run `function` with the private creation mask, restored afterwards
    whatever happens."""
    previous = os.umask(PRIVATE_UMASK)
    try:
        return function(*arguments)
    finally:
        os.umask(previous)


def _script_error(error):
    """Type, message and the standard traceback of `error`, starting at the
    script: the frames of the bridge itself are left out."""
    frames = error.__traceback__
    while frames is not None and frames.tb_frame.f_code.co_filename != SCRIPT_FILENAME:
        frames = frames.tb_next
    return {
        "type": type(error).__name__,
        "message": _text_of(error),
        "traceback": "".join(traceback.format_exception(type(error), error, frames)),
    }


def _script_result(namespace):
    """The `result` the script left, and a warning when it cannot be sent."""
    if "result" not in namespace:
        return None, ""
    value = namespace["result"]
    try:
        return _json_copy(value), ""
    except Exception as error:
        return None, "%sresult of type %s is not JSON serialisable (%s); null returned\n" % (
            _WARNING,
            type(value).__name__,
            type(error).__name__,
        )


def _run_script(adapter, script, work_dir):
    """Compile and run one script in a fresh namespace; never raises for what
    the script does, including SystemExit."""
    namespace = {"__name__": "__main__"}
    namespace.update(adapter.namespace())
    namespace["LMM_WORK_DIR"] = work_dir
    stdout, stderr = _Capture(), _Capture()
    outcome = {}

    def run():
        saved = sys.stdout, sys.stderr
        sys.stdout, sys.stderr = stdout, stderr
        try:
            code = compile(script, SCRIPT_FILENAME, "exec", dont_inherit=True)
            exec(code, namespace)
        except BaseException as error:  # a script must never stop the bridge
            outcome["error"] = _script_error(error)
        finally:
            sys.stdout, sys.stderr = saved

    _with_private_umask(run)
    error = outcome.get("error")
    result, warning = (None, "") if error else _script_result(namespace)
    if warning:
        stderr.write(warning)
    return {
        "ok": error is None,
        "stdout": stdout.text(),
        "stderr": stderr.text(),
        "result": result,
        "error": error,
    }


# --------------------------------------------------------------------------
# The server
# --------------------------------------------------------------------------


def _version_of(adapter):
    try:
        version = adapter.app_version()
    except Exception:
        return UNKNOWN_VERSION
    return version if isinstance(version, str) and version else UNKNOWN_VERSION


def _discard(connection):
    try:
        connection.close()
    except OSError:
        pass


class _Bridge:
    """One listening socket and at most one connection served at a time."""

    def __init__(self, adapter, port, token, hello_timeout):
        app = getattr(adapter, "app", None)
        if not isinstance(app, str) or not app:
            raise BridgeError("the adapter has no application name")
        self._adapter = adapter
        self._app = app
        # Read here, in the thread that starts the bridge: the application's
        # API is not called from the connection threads for the hello.
        self._app_version = _version_of(adapter)
        self._token = token
        self._hello_timeout = hello_timeout
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self._active = None
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listener.bind((LISTEN_ADDRESS, port))
            listener.listen(_LISTEN_BACKLOG)
            listener.settimeout(_ACCEPT_POLL_S)
        except BaseException:
            listener.close()
            raise
        self._listener = listener
        self.port = listener.getsockname()[1]
        self._thread = threading.Thread(
            target=self._accept_loop, name="libremodular-bridge", daemon=True
        )

    def begin(self):
        self._thread.start()

    def close(self):
        self._stop.set()
        _discard(self._listener)
        with self._lock:
            active = self._active
        if active is not None:
            try:
                active.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
        if self._thread.is_alive() and self._thread is not threading.current_thread():
            self._thread.join(timeout=2.0)

    def _accept_loop(self):
        while not self._stop.is_set():
            try:
                connection, peer = self._listener.accept()
            except socket.timeout:
                continue
            except OSError:
                if self._stop.is_set():
                    break
                time.sleep(_ACCEPT_POLL_S)
                continue
            if not _peer_allowed(peer):
                _discard(connection)
                continue
            with self._lock:
                taken = self._active is not None
                if not taken:
                    self._active = connection
            if taken:
                _discard(connection)
                continue
            worker = threading.Thread(
                target=self._serve,
                args=(connection,),
                name="libremodular-bridge-connection",
                daemon=True,
            )
            worker.start()

    def _serve(self, connection):
        try:
            self._converse(connection)
        except OSError:
            pass
        except Exception as error:
            _say("LMM bridge: connection ended on %s" % type(error).__name__)
        finally:
            _discard(connection)
            with self._lock:
                if self._active is connection:
                    self._active = None

    def _hello_is_valid(self, line):
        greeting = _parse_object(line)
        if greeting is None or greeting.get("type") != "hello":
            return False
        protocol = greeting.get("protocol")
        if type(protocol) is not int or protocol != PROTOCOL_VERSION:
            return False
        given = greeting.get("token")
        if not isinstance(given, str):
            return False
        try:
            given = given.encode("utf-8")
        except UnicodeError:
            return False
        return hmac.compare_digest(given, self._token)

    def _converse(self, connection):
        reader = _LineReader(connection)
        first = reader.read_line(time.monotonic() + self._hello_timeout)
        if first is None or not self._hello_is_valid(first):
            return
        connection.settimeout(None)
        _send(
            connection,
            {
                "type": "hello",
                "ok": True,
                "protocol": PROTOCOL_VERSION,
                "app": self._app,
                "app_version": self._app_version,
                "bridge_version": BRIDGE_VERSION,
            },
        )
        while not self._stop.is_set():
            line = reader.read_line(None)
            if line is None:
                return
            request = _parse_object(line)
            if request is None:
                return
            answer = self._answer(request)
            answer["id"] = request.get("id")
            _send(connection, answer)

    def _answer(self, request):
        kind = request.get("type")
        if kind == "ping":
            return {"ok": True}
        if kind == "execute":
            return self._execute(request)
        if kind == "state":
            return self._state(request)
        return _failure("UnknownRequest", "unknown request type")

    def _execute(self, request):
        script = request.get("script")
        work_dir = request.get("work_dir")
        if not isinstance(script, str) or not isinstance(work_dir, str):
            return _failure(
                "InvalidRequest", "an execute request needs a script and a work_dir as text"
            )
        started = time.monotonic()
        adapter = self._adapter
        try:
            answer = adapter.run_on_main(lambda: _run_script(adapter, script, work_dir))
        except Exception as error:
            answer = _failure(
                type(error).__name__,
                _text_of(error),
                "".join(traceback.format_exception(type(error), error, error.__traceback__)),
            )
            answer.update({"stdout": "", "stderr": "", "result": None})
        if not isinstance(answer, dict):
            answer = _failure("BridgeError", "the adapter did not hand back the outcome")
            answer.update({"stdout": "", "stderr": "", "result": None})
        answer["duration_ms"] = int((time.monotonic() - started) * 1000)
        return answer

    def _state(self, request):
        capture_path = request.get("capture_path")
        if capture_path is not None and not isinstance(capture_path, str):
            return _failure("InvalidRequest", "capture_path must be text or null")
        adapter = self._adapter
        warnings = []
        if self._app_version == UNKNOWN_VERSION:
            warnings.append(
                "the %s scripting API cannot be imported in this process" % self._app
            )
        state = {}
        try:
            reported = adapter.run_on_main(adapter.state)
            if not isinstance(reported, dict):
                raise TypeError("the adapter returned a %s" % type(reported).__name__)
            state = _json_copy(reported)
        except Exception as error:
            # Type and message only: a traceback would describe the bridge, not the document.
            warnings.append("state unavailable: %s: %s" % (type(error).__name__, _text_of(error)))
        screenshot = None
        if capture_path:
            try:
                written = adapter.run_on_main(
                    lambda: _with_private_umask(adapter.screenshot, capture_path)
                )
            except Exception as error:
                warnings.append(
                    "screenshot unavailable: %s: %s" % (type(error).__name__, _text_of(error))
                )
            else:
                if written is True:
                    screenshot = capture_path
        return {"ok": True, "state": state, "screenshot": screenshot, "warnings": warnings}


# --------------------------------------------------------------------------
# Starting and stopping
# --------------------------------------------------------------------------

_registry_lock = threading.Lock()
_running = None


def _say(line):
    """Write one line on the error stream of the process, and on the current
    error stream when an application redirected it to a console."""
    streams = []
    for stream in (sys.__stderr__, sys.stderr):
        if stream is not None and all(stream is not seen for seen in streams):
            streams.append(stream)
    for stream in streams:
        try:
            stream.write(line + "\n")
            stream.flush()
        except Exception:
            pass


def _check_port(port):
    if type(port) is not int or not 0 <= port <= 65535:
        raise BridgeError("the port must be a number between 0 and 65535")
    return port


def start(adapter, port, token_path, hello_timeout=HELLO_TIMEOUT_S):
    """Start the bridge in a background thread and return the port it listens on.

    `port` 0 lets the system choose a free port. `hello_timeout` is the time a
    new connection has to send its first line; only tests change it.
    """
    global _running
    _check_port(port)
    with _registry_lock:
        if _running is not None:
            raise BridgeError("a bridge is already running in this process; call stop() first")
        token = _read_token(token_path)
        bridge = _Bridge(adapter, port, token, float(hello_timeout))
        _running = bridge
    bridge.begin()
    _say("LMM bridge listening on %s:%d" % (LISTEN_ADDRESS, bridge.port))
    return bridge.port


def stop():
    """Stop listening and close the connection. A script still running ends on
    its own; the application itself is never touched."""
    global _running
    with _registry_lock:
        bridge, _running = _running, None
    if bridge is not None:
        bridge.close()


def _port_from_environment(text, default_port):
    if text is None or text == "":
        return default_port
    if len(text) > 5 or any(character not in "0123456789" for character in text):
        raise BridgeError("LIBREMODULAR_BRIDGE_PORT must be a port number")
    return _check_port(int(text))


def _default_token_path(environment):
    base = environment.get("XDG_CONFIG_HOME", "")
    if not os.path.isabs(base):
        home = environment.get("HOME", "")
        if not os.path.isabs(home):
            raise BridgeError(
                "cannot locate the token: set LIBREMODULAR_TOKEN_PATH or HOME"
            )
        base = os.path.join(home, ".config")
    return os.path.join(base, "libremodular-mcp", "token")


def _running_as_program():
    """True when this file is the program Python was asked to run, false when
    its text was executed inside an application's console."""
    own = _running_as_program.__code__.co_filename
    program = sys.argv[0] if sys.argv else ""
    if not program or own.startswith("<"):
        return False
    try:
        return os.path.samefile(own, program)
    except OSError:
        return False


def launch(adapter, default_port):
    """Start the bridge with the port and token path given by the environment.

    Inside an application this returns at once and the bridge serves in the
    background; run as a program, it serves until the process is stopped.
    """
    environment = os.environ
    port = _port_from_environment(environment.get("LIBREMODULAR_BRIDGE_PORT"), default_port)
    token_path = environment.get("LIBREMODULAR_TOKEN_PATH") or _default_token_path(environment)
    port = start(adapter, port, token_path)
    if _running_as_program():
        try:
            while True:
                time.sleep(3600)
        except KeyboardInterrupt:
            pass
        finally:
            stop()
    return port

# --- adapter: bridges/adapters/gimp.py ---------------------------------------

"""GIMP 3 adapter: the names a script receives, and how GIMP's state and captures are read.

Why this module exists
GIMP is reached through GObject Introspection and only accepts calls from its main
thread. This file is the only place that knows either, so the core stays the same
for every application. Written from the public GIMP 3.0 API; not tried in a real GIMP.
"""

import threading

DEFAULT_PORT = 9301


def _gimp():
    """The Gimp module, or None when this process cannot load it."""
    try:
        import gi

        gi.require_version("Gimp", "3.0")
        from gi.repository import Gimp
    except Exception:
        return None
    return Gimp


def _gio():
    try:
        from gi.repository import Gio
    except Exception:
        return None
    return Gio


def _glib():
    try:
        from gi.repository import GLib
    except Exception:
        return None
    return GLib


def _open_images(Gimp):
    return list(Gimp.get_images())


def images():
    """The images open in GIMP; the first one is the one the bridge describes
    as active."""
    Gimp = _gimp()
    return _open_images(Gimp) if Gimp is not None else []


def _nick(value):
    """The short name of a GObject enumeration value, such as "rgb" or "normal"."""
    nick = getattr(value, "value_nick", None)
    return nick if isinstance(nick, str) else str(value)


def _describe_image(image):
    return {
        "id": image.get_id(),
        "name": image.get_name(),
        "width": image.get_width(),
        "height": image.get_height(),
        "color_mode": _nick(image.get_base_type()),
    }


def _describe_layer(layer):
    return {
        "id": layer.get_id(),
        "name": layer.get_name(),
        "visible": bool(layer.get_visible()),
        "opacity": float(layer.get_opacity()),
        "blend_mode": _nick(layer.get_mode()),
    }


def _selection(Gimp, image):
    # Introspection returns (success, non_empty, x1, y1, x2, y2); the last five
    # values are read so that a binding without the leading flag reads the same.
    non_empty, x1, y1, x2, y2 = tuple(Gimp.Selection.bounds(image))[-5:]
    if not non_empty:
        return None
    return {"x": x1, "y": y1, "width": x2 - x1, "height": y2 - y1}


def _describe_active(Gimp, image):
    selected = list(image.get_selected_layers())
    return {
        "id": image.get_id(),
        "name": image.get_name(),
        "layers": [_describe_layer(layer) for layer in image.get_layers()],
        "active_layer": selected[0].get_id() if selected else None,
        "selection": _selection(Gimp, image),
    }


class GimpAdapter:
    """What the core needs from GIMP. Every call into GIMP happens in a method,
    so this file loads without GIMP."""

    app = "gimp"

    def app_version(self):
        Gimp = _gimp()
        if Gimp is None:
            return "unknown"
        try:
            version = Gimp.version()
        except Exception:
            return "unknown"
        return version if isinstance(version, str) and version else "unknown"

    def namespace(self):
        names = {}
        for name, module in (("Gimp", _gimp()), ("Gio", _gio()), ("GLib", _glib())):
            if module is not None:
                names[name] = module
        names["images"] = images
        return names

    def run_on_main(self, function):
        """Run `function` in GIMP's main thread and hand back its value or its
        exception. Without GLib, or from the main thread itself, it is a direct call."""
        GLib = _glib()
        if GLib is None or threading.current_thread() is threading.main_thread():
            return function()
        done = threading.Event()
        outcome = {}

        def call():
            try:
                outcome["value"] = function()
            except BaseException as error:  # raised again in the waiting thread
                outcome["error"] = error
            finally:
                done.set()
            return False  # run once

        GLib.idle_add(call)
        done.wait()
        if "error" in outcome:
            raise outcome["error"]
        return outcome.get("value")

    def state(self):
        Gimp = _gimp()
        if Gimp is None:
            return {}
        open_images = _open_images(Gimp)
        return {
            "images": [_describe_image(image) for image in open_images],
            "active_image": _describe_active(Gimp, open_images[0]) if open_images else None,
        }

    def screenshot(self, path):
        """Export a flattened copy of the active image as PNG. The copy keeps the
        user's image untouched: exporting it would change its export file name."""
        Gimp, Gio = _gimp(), _gio()
        if Gimp is None or Gio is None:
            return False
        open_images = _open_images(Gimp)
        if not open_images:
            return False
        copy = open_images[0].duplicate()
        try:
            copy.merge_visible_layers(Gimp.MergeType.CLIP_TO_IMAGE)
            saved = Gimp.file_save(
                Gimp.RunMode.NONINTERACTIVE, copy, Gio.File.new_for_path(path), None
            )
        finally:
            copy.delete()
        return bool(saved)


ADAPTER = GimpAdapter

# --- entry point, added by scripts/build_bridges.py ---------------------------

launch(ADAPTER(), DEFAULT_PORT)
